 ,B.AfterAdd,B.Condition
,B.BeforeAdd,B.AfterDelete
FROM Dev_DictionaryField(nolock) A
  INNER JOIN Dev_Dictionary(nolock) B ON A.DictionaryID=B.DictionaryID
where A.DictionaryID=" + dictionaryID + " AND A.IsSelect=1 ORDER BY A.FieldIndex");
            this.DtDictionary = dtDictionary;
