                                {
                                    foreach (string v in matchCollection)
                                    {
                                        string  v1 = v.Trim().Replace("'","''");
                                        if (!string.IsNullOrEmpty(v1))
                                        {
                                            orderSeq++;
                                            if (isNumericKey)
                                            {
                                              //  if(queryMethod!= QueryMethod.模糊匹配)
                                                {
                                                    queryMethod = QueryMethod.IN;
                                                }
                                         
                                                valueIn += "" + v1.Replace("'", "") + ",";
                                                orderByValues += "(" + orderSeq + "," + v1.Replace("'", "") + "),";
                                            }
                                            else
                                            {
                                                valueIn += "'" + v1.Replace("'", "") + "',";
                                                orderByValues += "(" + orderSeq + ",N'" + v1 + "'),";
                                                if(v.EndsWith("*"))
                                                {
                                                    v1 = " LIKE '" + v.TrimEnd('*') + "%'";
                                                }
                                                else if (v.StartsWith("*"))
                                                {
                                                    v1 = " LIKE '%" + v.TrimStart('*') + "'";
                                                }
                                                else
                                                {
                                                    v1 = " LIKE '%" + v.TrimStart('*') + "%'";
                                                }
                                                if(whereLike!="(")
                                                {
                                                     
                                                    if(queryMethod==QueryMethod.多个值与)
                                                    {
                                                        whereLike += " AND " + parameterName + v1;
                                                    }
                                                    else
                                                    {
                                                        whereLike += " OR " + parameterName + v1;
                                                    }
                                                   
                                                }
                                                 else
                                                {
                                                    whereLike += parameterName + v1;
                                                }
                                            }
                                        }
                                        else
                                        {
                                           // valueIn += "'',";
                                        }

                                    }
                                    whereLike += ")";
                                }
                                if (matchCollection.Length > 1&&!string.IsNullOrEmpty(valueIn)&&queryMethod!= QueryMethod.NOTIN&&queryMethod!= QueryMethod.范围)
                                {
                                    if(queryMethod== QueryMethod.模糊匹配|| queryMethod == QueryMethod.多个值与)
                                    {
                                        
                                        if ((DictionaryID == 7850 || DictionaryID == 7862) && parameterName.ToLower() == "POSuplierName".ToLower())
                                        {//EK查供应商
                                            ResultWhere += " AND "  +parameterName + " LIKE '%," + value.Replace("'", "''") + ",%'";
                                        }
                                        else
                                        {
                                            ResultWhere += " AND " + whereLike;
                                        }
                                    }
                                    else
                                    {
                                        ResultWhere += " AND  " + parameterName + " IN (" + valueIn.Trim(',') + ")";
                                    }

                                    // 先记下输入顺序；最终与字典 SortType / 前端 sort 拼接时再放到最前
                                    if (!string.IsNullOrEmpty(orderByValues))
                                    {
                                        string orderExpr = "ISNULL((SELECT TOP 1 Seq FROM (VALUES "
                                            + orderByValues.TrimEnd(',')
                                            + ") AS _apsOrd(Seq,Val) WHERE _apsOrd.Val=" + parameterName
                                            + "),2147483647)";
                                        searchOrderExprs.Add(orderExpr);
                                    }
                                 
                               
                                }
                                else
                                {

                                    string tmpstr = " AND ";
                                    if(IsUserOR)
                                    {
                                        tmpstr = " OR ";
                                    }
                                    switch (queryMethod)
                                    {
                                        default:
                                        case QueryMethod.模糊匹配:
                                           if(value== "null")
                                            {
                                                value = "";
                                            }
                                            if(value.StartsWith("<>"))
                                            {
                                                ResultWhere += tmpstr + parameterName + "" + value.Replace("'", "''") + "";
                                            }
                                            else
                                            {
                                                if(parameterName.ToLower()== "OrganizeIDs".ToLower())
                                                {
                                                    ResultWhere += tmpstr + parameterName + " LIKE '%$" + value.Replace("'", "''") + "$%'";
                                                }
                                                else
                                                {
                                                    if((DictionaryID==7850||DictionaryID==7862)&& parameterName.ToLower()== "POSuplierName".ToLower())
                                                    {//EK查供应商
                                                        ResultWhere += tmpstr + parameterName + " LIKE '%," + value.Replace("'", "''") + ",%'";
                                                    }
                                                    else
                                                    {
                                                        value = value.Replace("'", "''");
                                                        if (value.EndsWith("*"))
                                                        {
                                                            value = " LIKE '" + value.TrimEnd('*') + "%'";
                                                        }
                                                        else if (value.StartsWith("*"))
                                                        {
                                                            value = " LIKE '%" + value.TrimStart('*') + "'";
                                                        }
                                                        else
                                                        {
                                                            value = " LIKE '%" + value + "%'";
                                                        }
                                                        ResultWhere += tmpstr + parameterName + value;
                                                    }
                                                   
                                                }
                                              
                                            }
                                            break;
                                        case QueryMethod.包含逗号:
                                            ResultWhere += tmpstr + parameterName + " LIKE '%," + value.Replace("'", "''") + ",%'";
                                            break;
                                        case QueryMethod.右匹配:
                                            ResultWhere += tmpstr + parameterName + " LIKE '%" + value.Replace("'", "''") + "'";
                                            break;
                                        case QueryMethod.大于:
                                            if ((dr["ControlType"].ToString().ToLower() == "datebox" || dr["ControlType"].ToString().ToLower() == "el-date-picker"))
                                            {
                                                ResultWhere += tmpstr + parameterName + ">'" + value + "'";
                                            }
                                            else
                                            {
                                                ResultWhere += tmpstr + parameterName + ">" + value;
                                            }
                                            break;
                                        case QueryMethod.大于等于:
                                            if ((dr["ControlType"].ToString().ToLower() == "datebox" || dr["ControlType"].ToString().ToLower() == "el-date-picker"))
                                            {
                                                ResultWhere += tmpstr + parameterName + ">='" + value + "'";
                                            }
                                            else
                                            {
                                                ResultWhere += tmpstr + parameterName + ">=" + value;
                                            }
                                            break;
                                        case QueryMethod.小于:
                                            if((dr["ControlType"].ToString().ToLower() == "datebox" || dr["ControlType"].ToString().ToLower() == "el-date-picker"))
                                            {
                                                ResultWhere += tmpstr + parameterName + "<'" + value+"'";
                                            }
                                            else
                                            {
                                                ResultWhere += tmpstr + parameterName + "<" + value;
                                            }
                                           
                                            break;
                                        case QueryMethod.小于等于:
                                            if ((dr["ControlType"].ToString().ToLower() == "datebox" || dr["ControlType"].ToString().ToLower() == "el-date-picker"))
                                            {
                                                ResultWhere += tmpstr + parameterName + "<='" + value + "'";
                                            }
                                            else
                                            {
                                                ResultWhere += tmpstr + parameterName + "<=" + value;
                                            }
                                            break;
                                        case QueryMethod.左匹配:
                                            ResultWhere += tmpstr + parameterName + " LIKE '" + value.Replace("'", "") + "%'";
                                            break;
                                        case QueryMethod.精确匹配:
                                            ResultWhere += tmpstr + parameterName + "='" + value.Replace("'", "") + "'";
                                            break;
                                        case QueryMethod.IN:
                                            ResultWhere += tmpstr + parameterName + " IN(" + value.Trim(',') + ")";
                                            break;
                                        case QueryMethod.NOTIN:
                                            ResultWhere += tmpstr + parameterName + " NOT IN(" + value.Trim(',') + ")";
                                            break;
                                        case QueryMethod.Null:

                                            if (string.IsNullOrEmpty(value))
                                            {
                                                //where += " AND  (" + parameterName + " IS NULL OR )";
                                            }
                                            else
                                            {
                                                if (value == "null")
                                                {
                                                    ResultWhere += tmpstr + "ISNULL("+parameterName + ",'')=''";
                                                }
                                                else
                                                {
                                                    ResultWhere += tmpstr + "ISNULL(" + parameterName + ",'')<>''";
                                                }

                                            }
                                            break;
                                        case QueryMethod.大于0:
                                            if (string.IsNullOrEmpty(value))
                                            {
                                                //where += " AND  (" + parameterName + " IS NULL OR )";
                                            }
                                            else
                                            {
                                                if (value == "0")
                                                {
                                                    ResultWhere += tmpstr + "ISNULL(" + parameterName + ",0)<=0";
                                                }
                                                else
                                                {
                                                    ResultWhere += tmpstr + "ISNULL(" + parameterName + ",0)>0";
                                                }

                                            }

                                            break;
                                        case QueryMethod.范围:

                                            if (!string.IsNullOrEmpty(values[0]))
                                            {
                                                ResultWhere += " AND " + parameterName + ">='" + values[0] + "'";
                                            }
                                            if (values.Length > 1 && !string.IsNullOrEmpty(values[1]))
                                            {
                                                if (dr["ControlType"].ToString().ToLower() == "datebox"|| dr["ControlType"].ToString().ToLower() == "el-date-picker")
                                                {
                                                    ResultWhere += "  AND " + parameterName + "<'" + DateTime.Parse(values[1]).AddDays(1) + "'";
                                                }
                                                else
                                                {
                                                    ResultWhere += "  AND " + parameterName + "<='" + values[1] + "'";
                                                }

                                            }
                                            else if(values.Length==1)
                                            {
                                                if (dr["ControlType"].ToString().ToLower() == "datebox" || dr["ControlType"].ToString().ToLower() == "el-date-picker")
                                                {
                                                    ResultWhere += "  AND " + parameterName + "<'" + DateTime.Parse(values[0]).AddDays(1) + "'";
                                                }
                                            }

                                            break;

                                    }
                                }
                             
                            }
                            else
                            {
                                continue;
                            }

                            break;
                        case OperationType.Delete:
                            if (isKey)
                            {
                                ResultWhere += " AND " + parameterName + "=@" + parameterName;
                            }
                            break;
                        case OperationType.Update:
                            if (parameterName.ToLower() == "modifyedon")
                            {
                                value = DateTime.Now.ToString();
                            }
                            if (parameterName.ToLower() == "modifiedby")
                            {
                                value = dev_Account.Account;
                            }
                            if (parameterName.ToLower() == "modifiedbyname")
                            {
                                value = dev_Account.Name;
                            }
                            if (parameterName.ToLower() == "createdon" || parameterName.ToLower() == "createdby" || parameterName.ToLower() == "createdbyname")
                            {
                                continue;
                            }
                            if (isKey)
                            {
                                ResultWhere += " AND " + parameterName + "=@" + parameterName;
                            }
                            else
                            {

                                sql += parameterName + "=@" + parameterName + ",";
                            }
                         
                            break;
                        case OperationType.Insert:

                            if (parameterName.ToLower() == "modifyedon")
                            {
                                value = DateTime.Now.ToString();
                            }
                            if (parameterName.ToLower() == "modifiedby")
                            {
                                value = dev_Account.Account;
                            }
                            if (parameterName.ToLower() == "modifiedbyname")
                            {
                                value = dev_Account.Name;
                            }

                            if (parameterName.ToLower() == "createdon" || parameterName.ToLower() == "modifyedon")
                            {
                                value = DateTime.Now.ToString();
                            }
                            else if (parameterName.ToLower() == "createdby")
                            {
                                value = dev_Account.Account;
                            }
                            else if (parameterName.ToLower() == "status" && string.IsNullOrEmpty(value))
                            {
                                value = "1";
                            }
                            else if (parameterName.ToLower() == "createdbyname")
                            {
                                value = dev_Account.Name;
                            }
                            else if (parameterName.ToLower() == "OrganizeID".ToLower() && string.IsNullOrEmpty(value))
                            {
                                value = dev_Account.CenterID.ToString();
                            }
                            else if (isIdentity||string.IsNullOrEmpty(value))
                            {

                                continue;
                            }
                            if (dr["DefaultValue"].ToString().StartsWith("(") && dr["DefaultValue"].ToString().EndsWith(")"))
                            {
                                parameter += "" + dr["DefaultValue"].ToString() + ",";
                            }
                            else
                            {
                                parameter += "@" + parameterName + ",";
                            }
                            sql += parameterName + ",";

                            break;


                    }
                
                    
                    if (isDbNull == true && string.IsNullOrEmpty(value))
                    {
                        SqlParameters[rowIndex] = new SqlParameter("@" + parameterName, DBNull.Value);
                    }
                    else
                    {
                        SqlParameters[rowIndex] = new SqlParameter("@" + parameterName, value);
                    }

                    rowIndex++;
                }


            }

            //客户端排序
            string? sort = LicenceRuntime.Http.HttpContext?.Request.GetRequestValue("sort");
            string? order = LicenceRuntime.Http.HttpContext?.Request.GetRequestValue("order");

            if (JsToken != null)
            {
                try
                {
                    if (JsToken["sort"] != null && JsToken["sort"].ToString().Trim().EndsWith("null") == false)
                    {
                        sort = JsToken["sort"].ToString();

                        sort = sort.Replace("ending", "");
                    }

                }
                catch (Exception ex)
                { }

            }
            if (!string.IsNullOrEmpty(sort))
            {
                // 有多值输入保序时：前端列排序只能接在后面，不能整段覆盖
                bool hasSearchOrder = searchOrderExprs.Count > 0;
                string sortField = sort.Split(' ')[0];
                if (hasSearchOrder)
                {
                    if (orderBy.IndexOf(sortField, StringComparison.OrdinalIgnoreCase) < 0)
                    {
                        orderBy = orderBy.Trim(',') + "," + sort + " " + (order ?? "");
                    }
                }
                else if (orderBy.ToLower().IndexOf(sortField.ToLower()) == -1)
                {
                    orderBy = sort + " " + order + (string.IsNullOrEmpty(orderBy) || orderBy == sort ? "" : "," + orderBy);
                }
                else
                {
                    orderBy = sort;
                }

            }
            if (string.IsNullOrEmpty(orderBy))
            {
                orderBy = keyField;
            }
            //else
            //{

            //    orderBy = orderBy.Trim(',')+ "," +keyField;
            //}
            orderBy = orderBy.Trim(',');
            // 最终顺序：输入顺序 → 原有排序（字典 SortType / 前端 sort / 主键）
            if (searchOrderExprs.Count > 0)
            {
                string searchOrd = string.Join(",", searchOrderExprs);
                orderBy = string.IsNullOrEmpty(orderBy) ? searchOrd : (searchOrd + "," + orderBy);
            }
            int start = (pageIndex - 1) * pageSize;
            int end = start + pageSize - 1;
            if (operationType == OperationType.Select)
            {
                ResultWhere += organizeIDCondition;
            }


            switch (operationType)
            {

                case OperationType.Select:

                    #region 判定是否启用控制者
                    if(AppInfo.IsControlID&& dev_Account!=null&&  Dev_DictionaryFields.Where(m=>m.ParameterName== "ControlID").Count()==1&&this.TabelName.ToLower()!= "APS_OrderControl".ToLower())
                    {
                        string controlIDSQL = @"
                          SELECT [ControlID] 
                          FROM [dbo].[APS_OrderControl]
                          WHERE [Status]=1 and Account='" + dev_Account.Account + @"'
                             UNION ALL
                          SELECT [ControlID] 
                          FROM [dbo].[APS_OrderControl] A
						  INNER JOIN Dev_Organize B ON A.OrganizeID=B.OrganizeID
                          WHERE A.[Status]=1 and OrganizeIDs LIKE '%$" + dev_Account.CenterID + @"$%'
                                


                            ";


                        DataTable dataTable = SqlHelper.ExecuteDataTable(controlIDSQL);
                        if(dataTable.Rows.Count>0)
                        {

                            ResultWhere += @" AND ControlID IN("+ controlIDSQL + ")";
                        }
                    }

                    #endregion



                    if (string.IsNullOrEmpty(Fields))
                    {//指定字段
                        if(dev_DictionaryFields.Where(m=>m.ParameterName== "isChecked").Count()==0)
                        {
                            sql = @"SELECT ROW_NUMBER() OVER (ORDER BY {0}) AS 'RowNumber',CAST('false' as bit) as isChecked," + sql + ResultWhere + @"
ORDER BY {0} " + (pageSize > 0 ? @"OFFSET {1}
                    ROW FETCH NEXT " + pageSize + @" ROW ONLY
" : "");
                        }
          else
                        {
                            sql = @"SELECT ROW_NUMBER() OVER (ORDER BY {0}) AS 'RowNumber'," + sql + ResultWhere + @"
ORDER BY {0} " + (pageSize > 0 ? @"OFFSET {1}
                    ROW FETCH NEXT " + pageSize + @" ROW ONLY
" : "");
                        }
                        SQLOfCount = @"
                            ;SELECT COUNT(1) AS RecordCount from " + ObjectName + "(NOLOCK) WHERE  " + (IsUserOR ? "1=2 " : "1=1") + ResultWhere;
                    }
                   else
                    {
                        if (!string.IsNullOrEmpty(GroupBy))
                        {
                            // orderBy = fields.Substring(0, fields.IndexOf(','));
                            //分组查询需要独立计算记录数
                            SQLOfCount = @"
                            ;SELECT COUNT(1) AS RecordCount from " + "(SELECT " + sql + this.ResultWhere + " GROUP BY " + this.GroupBy + ") A ";
                            sql = "SELECT " + (this.PageSize > 0 ? " TOP " + this.PageSize.ToString() : "") + sql + this.ResultWhere + " GROUP BY " + this.GroupBy + (string.IsNullOrEmpty(orderBy) ? "" : " ORDER BY " + orderBy);

                        }
                        else
                        {
                           sql = "SELECT " +  sql + this.ResultWhere;
                            SQLOfCount = @"
                            ;SELECT COUNT(1) AS RecordCount from " + ObjectName + "(NOLOCK) WHERE  " + (IsUserOR ? "1=2 " : "1=1") + ResultWhere;
                        }

                    }
             

                    SQLOfSelect = sql;
                    
                
                    sql += SQLOfCount;
                    if (!string.IsNullOrEmpty(footSql))
                    {
                        sql += ";SELECT " + footSql.Trim(',') + " FROM " + ObjectName + "(nolock) WHERE " + (IsUserOR ? "1=2 " : "1=1") + ResultWhere;
                    }

                    break;
                case OperationType.Delete:
                case OperationType.Update:
                    sql = sql.Trim(',') + " WHERE 1=1   " + (string.IsNullOrEmpty(ResultWhere) ? " and 1=2" : ResultWhere);
                    break;
                case OperationType.Insert:
                    if (!string.IsNullOrEmpty(parameter))
                    {
                        parameter = parameter.Trim(',') + ")";
                    }
                    sql = sql.Trim(',') + parameter;

                    break;
            }
          

            SystemLog systemLog2 = new SystemLog();
            if (operationType == OperationType.Select)
            {//查询强制默认一个排序
                if (string.IsNullOrEmpty(orderBy) && this.Dev_DictionaryFields.Where(m => m.ParameterName.ToLower() == "createdon").Count() == 0)
                {//没有查询，并且没有创建日期，默认第一个排序
                    orderBy = this.Dev_DictionaryFields[0].ParameterName;
                }

                //if (this.Dev_DictionaryFields.Where(m => m.ParameterName.ToLower() == "createdon").Count()==1)
                {
                    sql = string.Format(sql.Trim(','), string.IsNullOrEmpty(orderBy) ? "createdon desc" : orderBy, start);
                    SQLOfSelect = string.Format(SQLOfSelect.Trim(','), string.IsNullOrEmpty(orderBy) ? "createdon desc" : orderBy, start);

                }

            }
            else if (operationType == OperationType.Update)
            {

                sql = sql.Trim(',');


                if (!string.IsNullOrEmpty(BeforeUpdate))
                {
                    sql = BeforeUpdate + ";" + sql;
                }
                if (!string.IsNullOrEmpty(AfterUpdate))
                {
                    sql += ";" + AfterUpdate;
                }
                // systemLog2.SaveLog(SystemLog.SystemLogType.SQL更新, sql);                                                                           
            }
            else if (operationType == OperationType.Insert)
            {

                sql = sql.Trim(',');
                if (!string.IsNullOrEmpty(AfterAdd))
                {
                    sql += ";" + AfterAdd;
                }
                if (!string.IsNullOrEmpty(AfterUpdate))
                {
                    // sql += ";" + AfterUpdate;
                }
                // systemLog2.SaveLog(SystemLog.SystemLogType.SQL添加, sql);
            }
            else if (operationType == OperationType.Delete)
            {

                sql = sql.Trim(',');
                if (!string.IsNullOrEmpty(AfterDelete))
                {
                    sql += ";" + AfterDelete;
                }
                // systemLog2.SaveLog(SystemLog.SystemLogType.SQL删除, sql);
            }
            OrderBy = orderBy;
            GetOperationType = operationType;
        }
