        /// </summary>
        /// <returns></returns>
        public DataSet GetDs(bool isQueryVisible=false)
        {
            IsQueryVisible = isQueryVisible;
            GetSql(OperationType.Select);

            Ds = SqlHelper.ExecuteDataset(SqlHelper.MSSQLConnectionString, CommandType.Text, sql, SqlParameters);



            RecoredCount = long.Parse(Ds.Tables[1].Rows[0][0].ToString());
            PageCount = Math.Ceiling(decimal.Parse(RecoredCount.ToString()) / (PageSize <= 0 ? 1M : PageSize));
            Dt = Ds.Tables[0];
            return Ds;
        }
