        /// <summary>
        /// 返回JSON对象
        /// </summary>
        /// <param name="dt"></param>
        /// <param name="recordCount"></param>
        /// <returns></returns>
        public JsonResult ToJson(DataSet ds, long recordCount, string parentID = "")
        {

            JsonResult json = new JsonResult();
            DataTable dt = ds.Tables[0];

            object[] rows = new object[dt.Rows.Count];
            object[] foots = new object[listFoot.Count];
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                Dictionary<string, object> dicColumn = new Dictionary<string, object>();

                foreach (DataColumn dc in dt.Columns)
                {
                    string name = dc.ColumnName;
                    object value = dt.Rows[i][name];

                    if (dc.DataType == typeof(DateTime))
                    {

                        if (!string.IsNullOrEmpty(value.ToString()))
                        {
                            value = string.Format("{0:MM/dd/yyyy HH:mm:ss}", value);
                        }
                        else
                        {
                            value = "";
                        }


                    }
                    else if (dc.DataType == typeof(decimal))
                    {
                        value = string.Format("{0:G0}", value);
                    }

                    dicColumn.Add(name, value.ToString());
                    //选中
                    if (name == "UIIsCheck")
                    {
                        dicColumn.Add("checked", value.ToString().ToLower() == "true" ? "true" : "");

                    }


                }
                if (dt.Columns.Contains(parentID))
                {


                    string pid = dt.Rows[i][parentID].ToString();
                    //if(dt.Columns[parentID].DataType==typeof(int)|| dt.Columns[parentID].DataType == typeof(long))
                    //{
                    //    if(string.IsNullOrEmpty(pid))
                    //    {
                    //        pid = "0";
                    //    }
                    //}
                    if (!string.IsNullOrEmpty(parentID) && pid != "")
                    {
                        dicColumn.Add("_parentId", pid);
                    }
                }
                rows[i] = dicColumn;
            }
            if (ds.Tables.Count >= 3)
            {
                DataTable dataTable = ds.Tables[2];
                int footIndex = 0;
                foreach (string s in listFoot)
                {
                    Dictionary<string, object> dicColumn = new Dictionary<string, object>();
                    bool isShowFoot = false;
                    for (int i = 0; i < dataTable.Rows.Count; i++)
                    {



                        foreach (DataColumn dcParent in dt.Columns)
                        {
                            bool isFindColumn = false;
                            foreach (DataColumn dc in dataTable.Columns)
                            {

                                string name = dc.ColumnName;
                                if (name == s + dcParent.ColumnName)
                                {
                                    isFindColumn = true;

                                    object value = dataTable.Rows[i][name];
                                    dicColumn.Add(dcParent.ColumnName, value.ToString());
                                }

                            }
                            if (!isFindColumn)
                            {
                                string value = "";
                                if (!isShowFoot)
                                {
                                    isShowFoot = true;
                                    value = s + "：";
                                }
                                dicColumn.Add(dcParent.ColumnName, value);
                            }

                            //选中
                        }

                    }
                    foots[footIndex] = dicColumn;
                    footIndex++;
                }
            }
            json.Data = new { total = recordCount, rows = rows, footer = foots };
            json.JsonRequestBehavior = JsonRequestBehavior.AllowGet;
            json.MaxJsonLength = int.MaxValue;
            return json;
        }
        /// <summary>
        /// 返回层级JSON对象
        /// </summary>
        /// <param name="dt"></param>
        /// <param name="recordCount"></param>
        /// <param name="parentID"></param>
        /// <returns></returns>
        public string ToJson(DataTable dt, int recordCount, string id, string parentID)
        {

            return @"{""total"":" + recordCount + @",""rows"":" + AddNode(dt, recordCount, id, parentID, "", 1) + "}";
        }
        /// <summary>  
        /// 无限递归，生成easyui tree可用的json数据 wyw308  
        /// </summary>  
        /// <param name="ParentID">父id</param>  
        /// <param name="deep">开始深度，默认为1</param>  
        /// <returns></returns>  
        private static string AddNode(DataTable dt, int recordCount, string id, string parentID, string parentIDValue, int deep)
        {
            string str = "";


            DataView dvTree = new DataView(dt);
            if (dt.Columns[parentID].DataType == typeof(string))
            {
                dvTree.RowFilter = "IsNull(" + parentID + ",'')='" + parentIDValue + "'";//过滤出ParentId  
            }
            else
            {
                if (string.IsNullOrEmpty(parentIDValue))
                {
                    parentIDValue = "0";
                }
                dvTree.RowFilter = "IsNull(" + parentID + ",'0')='" + parentIDValue + "'";//过滤出ParentId  
            }


            int i = 0;
            int d = deep;
            foreach (DataRowView drv in dvTree)
            {

                if (i == 0)//如果是某一层的开始，需要“[”开始  
                {
                    if (d == 1)//如果深度为1,即第一层  
                        str = "[";
                    else//否则，为第二层或更深  
                        str = ",\"children\":[";
                }

                else
                    str = str + ",";



                str = str + "{";
                foreach (DataColumn dc in dt.Columns)
                {
                    object value = drv[dc.ColumnName];
                    if (dc.DataType == typeof(DateTime))
                    {

                        if (!string.IsNullOrEmpty(value.ToString()))
                        {
                            value = string.Format("{0:MM/dd/yyyy HH:mm:ss}", value);
                        }
                        else
                        {
                            value = "";
                        }


                    }
                    str = str + "\"" + dc.ColumnName + "\":\"" + value.ToString().Replace("'", "\'").Replace("\"", "\\\"") + "\",";
                }
                str = str.TrimEnd(',');


                str = str + AddNode(dt, recordCount, id, parentID, drv[id].ToString(), deep + 1);//递归  

                str = str + "}";
                i = i + 1;

                if (dvTree.Count == i)//如果某一层到了末尾,需要"]"结束  
                    str = str + "]";

            }

            return str;
        }
        public static DataTable GetFieldByTableName(string tableName)
        {

            SqlParameter[] sqlParameters = new SqlParameter[1];
            sqlParameters[0] = new SqlParameter("@TableName", tableName);

            DataSet ds = SqlHelper.ExecuteDataset(SqlHelper.MSSQLConnectionString, "P_GetFieldByTableName", sqlParameters);
            return ds.Tables[0];


        }

