        /// <summary>
        /// 判定字段类型是否应该存为dbnull
        /// </summary>
        /// <param name="parameterName">字段</param>
        /// <param name="dataType">类型</param>
        /// <returns></returns>
        public static bool IsDbNull(string parameterName, string dataType)
        {
            bool result = false;
            switch (dataType.ToLower())
            {
                case "int":
                case "decimal":
                case "datetime":
                case "bigint":
                case "bit":
                case "float":
                case "numeric":
                case "real":
                    result = true;
                    break;

            }
            return result;
        }
