        /// <summary>
        /// 根据字符返回NULL或者字符
        /// </summary>
        /// <param name="value"></param>
        /// <returns></returns>
        public static string GetStringOrNull(string value)
        {
            if (string.IsNullOrEmpty(value))
            {
                return "NULL";
            }
            else
            {
                return "'" + value.Replace("'", "''") + "'";
            }
        }

        /// <summary>el-date-picker / datebox 范围查询：解析 ISO、JSON 数组或字符串化数组。</summary>
        private static string NormalizeDateRangeQueryValue(string raw)
        {
            if (string.IsNullOrWhiteSpace(raw))
                return string.Empty;

            raw = raw.Trim();
            if (raw.StartsWith('['))
            {
                try
                {
                    if (JToken.Parse(raw) is JArray arr && arr.Count > 0)
                    {
                        return string.Join(",",
                            arr.Select(t => NormalizeSingleDateQueryValue(t.ToString()))
                                .Where(s => !string.IsNullOrEmpty(s)));
                    }
                }
                catch
                {
                    // fallback: comma split below
                }
            }

            return string.Join(",",
                raw.Split(',')
                    .Select(NormalizeSingleDateQueryValue)
                    .Where(s => !string.IsNullOrEmpty(s)));
        }

        private static string NormalizeSingleDateQueryValue(string? raw)
        {
            if (string.IsNullOrWhiteSpace(raw))
                return string.Empty;

            var s = raw.Trim().Trim('"', '\'');
            s = s.Replace("\r", string.Empty).Replace("\n", string.Empty).Replace("\\", string.Empty);
            if (s.Contains('T', StringComparison.Ordinal))
                s = s.Replace("Z", string.Empty, StringComparison.OrdinalIgnoreCase).Replace("T", " ");

            var plus = s.IndexOf('+');
            if (plus > 10)
                s = s[..plus].Trim();

            if (DateTimeOffset.TryParse(s, CultureInfo.InvariantCulture, DateTimeStyles.AllowWhiteSpaces, out var dto))
                return dto.LocalDateTime.ToString("yyyy-MM-dd HH:mm:ss");
            if (DateTime.TryParse(s, out var dt))
                return dt.ToString("yyyy-MM-dd HH:mm:ss");

            return s;
        }

    }
